import shutil, openpyxl, re
shutil.copy(INIT, OUT)
vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)
ws = wb[vals.active.title]

# find lookup sheet
lookup_name = None
for name in vals.sheetnames:
    if name == ws.title: continue
    if 'URN' in name.upper() and 'LOOKUP' in name.upper():
        lookup_name = name; break
if lookup_name is None:
    for name in vals.sheetnames:
        if name != ws.title and 'URN' in name.upper():
            lookup_name = name; break
if lookup_name is None:
    # maybe no lookup, leave B as None? 
    for r in range(2,1462): ws.cell(row=r,column=2).value = None
    wb.save(OUT); exit
lws = vals[lookup_name]
max_lookup = max(1461, lws.max_row or 1)
k_vals=[]; d_vals=[]
for r in range(2, max_lookup+1):
    k_vals.append(lws.cell(row=r, column=11).value)
    d_vals.append(lws.cell(row=r, column=4).value)

def canon(v):
    if v is None: return None
    if isinstance(v, bool):
        return ('text', str(v).upper())
    if isinstance(v, (int, float)):
        if isinstance(v, float) and v.is_integer(): v = int(v)
        return ('num', v)
    s = str(v).strip()
    if not s: return None
    # try numeric
    try:
        f = float(s)
        if f.is_integer(): return ('num', int(f))
        return ('num', f)
    except Exception:
        pass
    # remove all whitespace, uppercase
    s2 = re.sub(r'\s+', '', s).upper()
    if not s2: return None
    return ('text', s2)

lookup_map = {}
num_k=0; text_k=0
for k,d in zip(k_vals,d_vals):
    key = canon(k)
    if key is None: continue
    if key[0]=='num': num_k += 1
    else: text_k += 1
    if key not in lookup_map:
        lookup_map[key] = d

# candidate columns: C=3, L=12, A=1, E=5? 
# Determine primary
# If K numeric, use C; if K text, use L. But if match rates strongly favor other, use other.
def count_matches(col):
    cnt=0
    for r in range(2, 1462):
        v = ws.cell(row=r, column=col).value
        key = canon(v)
        if key is not None and key in lookup_map:
            cnt += 1
    return cnt
match_C = count_matches(3)
match_L = count_matches(12)
# maybe match_A, match_E if needed
if num_k > text_k:
    primary = 3
elif text_k > num_k:
    primary = 12
else:
    primary = 12 if match_L >= match_C else 3
# If primary has very low matches and other high, switch? 
if primary == 3 and match_C < 10 and match_L > match_C + 10:
    primary = 12
if primary == 12 and match_L < 10 and match_C > match_L + 10:
    primary = 3

# write
for r in range(2, 1462):
    v = ws.cell(row=r, column=primary).value
    key = canon(v)
    if key is not None and key in lookup_map:
        val = lookup_map[key]
        if isinstance(val, str):
            val = val.strip()
        # if val is float integer? maybe convert to int?
        if isinstance(val, float) and val.is_integer():
            val = int(val)
        ws.cell(row=r, column=2).value = val
    else:
        # no match: leave empty
        ws.cell(row=r, column=2).value = None
